public class LongestOnes {
    public static int longestConsecutiveOnes(String s) {
        if (s == null || s.isEmpty()) {
            return 0;
        }

        int maxLen = 0;
        int currentLen = 0;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') {
                currentLen++;
                if (currentLen > maxLen) {
                    maxLen = currentLen;
                }
            } else {
                currentLen = 0;
            }
        }

        return maxLen;
    }
}
