def bellman_ford(graph, source, num_vertices):
    """
    Implements the Bellman-Ford algorithm to find shortest paths from a source node.

    Args:
        graph: List of edges as (u, v, w) tuples.
        source: Starting node (string).
        num_vertices: Total number of vertices.

    Returns:
        Dictionary mapping each node to its shortest distance from source,
        or "Negative weight cycle detected" if a negative cycle is reachable.
    """
    # Initialize distances
    dist = {node: float('inf') for node in range(num_vertices)}
    dist[source] = 0

    # Map node names to indices (0..num_vertices-1)
    node_to_idx = {node: i for i, node in enumerate(range(num_vertices))}
    idx_to_node = {i: node for i, node in enumerate(range(num_vertices))}

    # Relax edges num_vertices - 1 times
    for _ in range(num_vertices - 1):
        updated = False
        for u, v, w in graph:
            # Convert node names to indices
            if u not in node_to_idx or v not in node_to_idx:
                continue  # Skip invalid nodes if any
            i_u, i_v = node_to_idx[u], node_to_idx[v]

            if dist[i_u] != float('inf') and dist[i_u] + w < dist[i_v]:
                dist[i_v] = dist[i_u] + w
                updated = True
        if not updated:
            break

    # Check for negative weight cycles
    for u, v, w in graph:
        if u not in node_to_idx or v not in node_to_idx:
            continue
        i_u, i_v = node_to_idx[u], node_to_idx[v]

        if dist[i_u] != float('inf') and dist[i_u] + w < dist[i_v]:
            return "Negative weight cycle detected"

    # Convert distances back to node names
    result = {}
    for i, node in enumerate(range(num_vertices)):
        result[node] = dist[i]

    return result

