def replace_question_marks(s: str) -> str:
    """ Replace each question mark in the input string with a lowercase letter such that no two adjacent characters are the same.
    >>> replace_question_marks("a?c")
    'abc'
    >>> replace_question_marks("?????")
    'abcde'  # any valid output is acceptable
    >>> replace_question_marks("ab??ba")
    'abacba'  # or 'ababba', etc.
    """
    result = list(s)
    for i in range(len(result)):
        if result[i] == '?':
            # Try lowercase letters 'a' through 'z'
            for c in "abcdefghijklmnopqrstuvwxyz":
                if i > 0 and c == result[i - 1]:
                    continue
                if i < len(result) - 1 and c == result[i + 1]:
                    continue
                result[i] = c
                break
    return "".join(result)

