import os
from pathlib import Path

def get_dir_size(path: Path) -> int:
    """Return total size of all files under `path` in bytes."""
    total = 0
    for entry in path.rglob("*"):
        if entry.is_file():
            try:
                total += entry.stat().st_size
            except OSError:
                # Skip files we can't stat (e.g., broken links)
                continue
    return total

