#!/usr/bin/env python3
import os
from pathlib import Path
from collections import Counter

def get_dir_size_with_types(path: Path) -> dict:
    """Return total size per file extension (or no extension)."""
    sizes = Counter()
    for entry in path.rglob("*"):
        if entry.is_file():
            try:
                size = entry.stat().st_size
                ext = entry.suffix.lower()
                if ext:
                    sizes[ext] += size
                else:
                    sizes[""] += size
            except OSError:
                continue
    return sizes

if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        print("Usage: python disk_usage.py <directory>")
        sys.exit(1)

    directory = Path(sys.argv[1])

    if not directory.is_dir():
        print(f"Error: '{directory}' is not a directory.")
        sys.exit(1)

    total_bytes = sum(get_dir_size_with_types(directory).values())
    total_gb = total_bytes / (1024 ** 3)

    print(f"Total size of '{directory}': {total_bytes:,} bytes ({total_gb:.2f} GB)")
    print("\nSize by file type:")
    for ext, size in sorted(get_dir_size_with_types(directory).items(), key=lambda x: -x[1]):
        ext_label = ext if ext else "(no extension)"
        print(f"  {ext_label}: {size:,} bytes")

