import sys

def check_if_valid(nums):
    """
    Determines if the array can become non-decreasing by modifying at most one element.

    Args:
        nums (list[int]): List of integers.

    Returns:
        bool: True if possible, False otherwise.
    """
    n = len(nums)
    if n <= 1:
        return True

    count = 0  # number of modifications allowed

    for i in range(1, n):
        if nums[i] < nums[i - 1]:
            count += 1
            if count > 1:
                return False

            # Decide whether to modify nums[i-1] or nums[i]
            # We prefer to modify nums[i-1] if possible to keep the sequence non-decreasing.
            # Exception: if i == 0, we can't modify nums[-1], but that case is handled by loop start.
            if i > 0 and i < n - 1:
                if nums[i - 1] > nums[i + 1]:
                    # Modifying nums[i-1] would break the next pair, so modify nums[i] instead
                    nums[i] = nums[i - 1]
                else:
                    # Modifying nums[i-1] is safe
                    nums[i - 1] = nums[i]
            elif i == 0:
                # This case shouldn't happen because loop starts at 1
                pass
            elif i == n - 1:
                # Last element: just modify nums[i-1] to be <= nums[i]
                nums[i - 1] = nums[i]

    return True

