from collections import Counter

def most_frequent_integers(nums):
    """
    Returns the integer that appears most frequently in the list.
    If there are ties, returns the first one encountered in the list.
    """
    if not nums:
        raise ValueError("Input list cannot be empty.")

    counter = Counter(nums)
    # Find the maximum frequency
    max_freq = max(counter.values())
    # Return the first element with that frequency (in order of appearance)
    for x in nums:
        if counter[x] == max_freq:
            return x

