def longest_subarray_sum_le_k(nums, k):
    left = 0
    current_sum = 0
    max_len = 0

    for right in range(len(nums)):
        current_sum += nums[right]

        while current_sum > k and left <= right:
            current_sum -= nums[left]
            left += 1

        if current_sum <= k:
            max_len = max(max_len, right - left + 1)

    return max_len

def unique_paths(m: int, n: int) -> int:
    # Create a DP table of size m x n
    dp = [[0] * n for _ in range(m)]

    # Base case: starting position
    dp[0][0] = 1

    # Fill first row
    for j in range(1, n):
        dp[0][j] = 1

    # Fill first column
    for i in range(1, m):
        dp[i][0] = 1

    # Fill the rest of the table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

def min_moves_to_non_decreasing(arr):
    if not arr:
        return 0

    moves = 0
    prev = arr[0]

    for i in range(1, len(arr)):
        curr = arr[i]
        if curr < prev:
            diff = prev - curr
            moves += diff
            # After increasing, this element becomes equal to prev
            # So prev stays the same for the next comparison
        else:
            prev = curr

    return moves

