def transpose_dict(input_dict):
    """
    Transposes a dictionary of lists.

    Each key in the input maps to a list of values.
    The function returns a dictionary where:
      - keys are the indices (0, 1, 2, ...)
      - values are dictionaries mapping original keys to the value at that index.

    Raises:
        ValueError: If any two lists have different lengths.
    """
    if not input_dict:
        return {}

    # Get all lists and their lengths
    lengths = [len(v) for v in input_dict.values()]

    # Check that all lists have the same length
    if not all(l == lengths[0] for l in lengths):
        raise ValueError("All lists in the input dictionary must have the same length.")

    n = lengths[0]
    transposed = {}

    for i in range(n):
        row = {}
        for key, values in input_dict.items():
            row[key] = values[i]
        transposed[i] = row

    return transposed

