from typing import List

def longest_increasing_subsequence_length(sequence: List[int]) -> int:
    """
    Returns the length of the longest increasing subsequence in the given sequence.

    Examples:
    >>> longest_increasing_subsequence_length([5, 2, 8, 6, 3, 6])
    3
    >>> longest_increasing_subsequence_length([1, 2, 3, 4, 5])
    5
    """
    if not sequence:
        return 0

    # tails[i] is the smallest tail of all increasing subsequences of length i+1
    tails = []

    for x in sequence:
        # Binary search for the first element in tails >= x
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid

        # If x is larger than all tails, extend the LIS
        if left == len(tails):
            tails.append(x)
        else:
            # Otherwise, replace the first element >= x with x
            tails[left] = x

    return len(tails)

