def is_permutation(a, b):
    if len(a) != len(b):
        return False

    counter = {}
    for num in a:
        counter[num] = counter.get(num, 0) + 1

    for num in b:
        if num not in counter:
            return False
        counter[num] -= 1
        if counter[num] == 0:
            del counter[num]

    return len(counter) == 0

def is_permutation(a, b):
    if len(a) != len(b):
        return False

    min_val = min(a)
    max_val = max(b)
    offset = -min_val
    size = max_val - min_val + 1

    counter = [0] * size

    for num in a:
        counter[num + offset] += 1

    for num in b:
        idx = num + offset
        if counter[idx] == 0:
            return False
        counter[idx] -= 1

    return all(c == 0 for c in counter)

