def most_recently_modified(directory: str) -> tuple[Path | None, float | None]:
    """
    Return (file_path, mtime) of the most recently modified file in directory.
    If no files are found, return (None, None).
    """
    latest_path = None
    latest_mtime = None

    for root, dirs, files in os.walk(directory):
        for name in files:
            file_path = os.path.join(root, name)
            try:
                mtime = os.path.getmtime(file_path)
            except (OSError, PermissionError):
                # Skip files we can't stat
                continue

            if latest_mtime is None or mtime > latest_mtime:
                latest_mtime = mtime
                latest_path = file_path

    return (Path(latest_path) if latest_path else None, latest_mtime)

