from collections import deque
from typing import List, Tuple

def determine_capital(N: int, M: int, A: int, B: int, residents: List[int], roads: List[Tuple[int, int]]) -> int:
    # Build adjacency list
    adj = [[] for _ in range(N + 1)]
    for u, v in roads:
        adj[u].append(v)
        adj[v].append(u)

    def max_dist_from_capital(cap: int) -> int:
        # BFS to find shortest distances from cap to all other cities
        dist = [-1] * (N + 1)
        dist[cap] = 0
        q = deque([cap])

        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)

        # Consider only cities that have residents
        max_d = 0
        for city, count in enumerate(residents, start=1):
            if count > 0:
                if dist[city] != -1:
                    max_d = max(max_d, dist[city])
                else:
                    # Unreachable city with residents -> effectively infinite
                    return float('inf')
        return max_d

    dist_A = max_dist_from_capital(A)
    dist_B = max_dist_from_capital(B)

    if dist_A < dist_B:
        return A
    elif dist_B < dist_A:
        return B
    else:
        return min(A, B)

def most_frequent_char(s: str) -> str:
    # Count occurrences of each character
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    # Track the character with max frequency; ties are broken by first appearance
    max_char = ''
    max_count = -1
    first_seen = {}

    for ch in s:
        if ch not in first_seen:
            first_seen[ch] = len(first_seen)  # index of first appearance
        count = counts[ch]
        if count > max_count:
            max_count = count
            max_char = ch

