def smallest_subarray_with_sum_greater_than_x(arr: list[int], x: int) -> int:
    n = len(arr)
    if n == 0:
        return 0

    left = 0
    current_sum = 0
    min_len = float('inf')

    for right in range(n):
        current_sum += arr[right]

        # Shrink the window from the left as long as sum > x
        while current_sum > x:
            current_len = right - left + 1
            if current_len < min_len:
                min_len = current_len
            current_sum -= arr[left]
            left += 1

        # Early exit if we found a subarray of length 1
        if min_len == 1:
            return 1

    return 0 if min_len == float('inf') else min_len

def findRepeatedPhrases(text: str, phraseLength: int) -> list[str]:
    # Split the text into words
    words = text.split()

    # If the text is too short to contain any phrase of the given length
    if len(words) < phraseLength:
        return []

    # Dictionary to store first occurrence index and count of each phrase
    phrase_info = {}  # phrase -> (first_index, count)

    # Extract all phrases of the given length
    for i in range(len(words) - phraseLength + 1):
        phrase = " ".join(words[i:i + phraseLength])
        if phrase not in phrase_info:
            phrase_info[phrase] = (i, 0)
        phrase_info[phrase][1] += 1  # increment count

    # Collect phrases that appear more than once, preserving first appearance order
    result = []
    for phrase, (first_index, count) in phrase_info.items():
        if count > 1:
            result.append(phrase)

    return result

from typing import List

def kth_smallest_element(nums: List[int], k: int) -> int:
    """
    Find the kth smallest element in an unsorted list using Quickselect.

    Time complexity: average O(n), worst case O(n^2) (can be improved with random pivot).
    Space complexity: O(1) auxiliary (ignoring recursion stack).

    Parameters:
        nums (List[int]): List of integers.
        k (int): 1-based index of the element to find (kth smallest).

    Returns:
        int: The kth smallest element.

    Raises:
        ValueError: If the list is empty.
    """
    if not nums:
        raise ValueError("List is empty")

    if k < 1 or k > len(nums):
        raise ValueError("k is out of bounds")

    def quickselect(arr: List[int], k: int) -> int:
        # Random pivot to avoid worst-case on sorted/reverse-sorted inputs
        import random
        pivot_index = random.randint(0, len(arr) - 1)
        pivot = arr[pivot_index]

        # Partition: elements < pivot, == pivot, > pivot
        left = []
        middle = []
        right = []

        for x in arr:
            if x < pivot:
                left.append(x)
            elif x == pivot:
                middle.append(x)
            else:
                right.append(x)

        # Determine which partition contains the kth element
        if k <= len(left):
            return quickselect(left, k)
        elif k <= len(left) + len(middle):
            return pivot
        else:
            return quickselect(right, k - len(left) - len(middle))

    return quickselect(nums, k)

