    # We can use a 2D list or even modify the grid in-place to save space.
    # Here we use a separate dp table for clarity.

    dp = [[0] * m for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1':
                if i == 0 or j == 0:
