                    # The size of the square ending at (i,j) is limited by the
                    # smallest square ending at (i-1,j), (i,j-1), and (i-1,j-1)
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                if dp[i][j] > max_side:
                    max_side = dp[i][j]
            else:
                dp[i][j] = 0

    print(max_side)

