from typing import List, Tuple

def is_hamiltonian_cycle(n: int, edges: List[Tuple[int, int]]) -> str:
    """ 
    Check if it is possible to create a sequence such that every student can pass the baton exactly once to one of their friends.
    """
    if n == 0:
        return "impossible"

    # Special case for n=2: A single edge (1, 2) allows 1->2->1
    if n == 2:
        if len(edges) == 1 and edges[0] == (1, 2) or edges[0] == (2, 1):
            return "possible"
        return "impossible"

    # Build adjacency list
    adj = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check basic necessary conditions:
    # 1. Every node must have at least 2 neighbors (for n > 2)
    # 2. The graph must be connected (implicitly checked by the DFS finding a path of length n)
    for i in range(1, n + 1):
        if len(adj[i]) < 2:
            return "impossible"

    # Backtracking to find Hamiltonian Cycle
    visited = [False] * (n + 1)

    def backtrack(node: int, count: int) -> bool:
        if count == n:
            # Check if we can return to the start node (node 1)
            return 1 in adj[node]

        for neighbor in adj[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                if backtrack(neighbor, count + 1):
                    return True
                visited[neighbor] = False
        return False

    # Start DFS from node 1
    visited[1] = True
    return "possible" if backtrack(1, 1) else "impossible"

