def update_inventory(inventory: dict, transactions: list) -> dict:
    """
    Update inventory based on a list of buy/return transactions.

    Parameters:
        inventory (dict): Current stock {product: quantity}
        transactions (list): List of (product, action) tuples
                            action is either "buy" or "return"

    Returns:
        dict: Updated inventory after processing all transactions.
    """
    for product, action in transactions:
        if action == "buy":
            if inventory[product] == 0:
                print(f"Error: Cannot buy '{product}' as it is out of stock.")
                continue
            inventory[product] -= 1
        elif action == "return":
            inventory[product] += 1
        else:
            # Optional: handle unexpected actions if needed
            continue

    return inventory


