def sum_of_primes_up_to_n(n: int) -> int:
    """
    Returns the sum of all prime numbers from 1 to n (inclusive).
    Time complexity: O(n log log n)
    Space complexity: O(n)
    """
    if n < 2:
        return 0

    # Sieve of Eratosthenes to mark non-primes
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            # Mark multiples of i starting from i*i
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    # Sum all marked primes
    return sum(i for i, prime in enumerate(is_prime) if prime)

