from typing import List

def longest_increasing_or_decreasing_subsequence(n: int, heights: List[int]) -> int:
    """
    Returns the length of the longest subsequence of trees with heights that are either
    strictly increasing or strictly decreasing.

    Time Complexity: O(n log n)
    Space Complexity: O(n)
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    # LIS (strictly increasing)
    inc = []
    for h in heights:
        # binary search for insertion point
        lo, hi = 0, len(inc)
        while lo < hi:
            mid = (lo + hi) // 2
            if inc[mid] < h:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(inc):
            inc.append(h)
        else:
            inc[lo] = h

    # LDS (strictly decreasing)
    dec = []
    for h in heights:
        # binary search for insertion point
        lo, hi = 0, len(dec)
        while lo < hi:
            mid = (lo + hi) // 2
            if dec[mid] > h:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(dec):
            dec.append(h)
        else:
            dec[lo] = h

    return max(len(inc), len(dec))

