def count_clusters(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    clusters = 0

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def dfs(r, c, val):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            r, c = stack.pop()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n:
                    if not visited[nr][nc] and grid[nr][nc] == val:
                        visited[nr][nc] = True
                        stack.append((nr, nc))

    for r in range(m):
        for c in range(n):
            if not visited[r][c]:
                clusters += 1
                dfs(r, c, grid[r][c])

    return clusters

