from typing import List

def find_triplets(arr: List[int], target: int) -> List[List[int]]:
    """
    Finds all unique triplets in the array that add up to the target sum. Each triplet should be sorted in ascending order, and the list of triplets should be sorted in lexicographical order. Returns an empty list if no such triplets exist.
    """
    arr.sort()
    n = len(arr)
    result = []

    for i in range(n - 2):
        # Skip duplicate i
        if i > 0 and arr[i] == arr[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            s = arr[i] + arr[left] + arr[right]
            if s == target:
                result.append([arr[i], arr[left], arr[right]])
                # Skip duplicates for left
                while left < right and arr[left] == arr[left + 1]:
                    left += 1
                # Skip duplicates for right
                while left < right and arr[right] == arr[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif s < target:
                left += 1
            else:
                right -= 1

    return result

