def minimum_trips(weights: List[int], limit: int) -> int:
    # If any package exceeds the limit, it cannot be delivered without exceeding.
    # We'll return -1 to indicate impossibility, though problem may assume valid input.
    if any(w > limit for w in weights):
        return -1  # or handle as per requirements; but problem doesn't specify

    # Sort weights in descending order for First-Fit Decreasing
    weights.sort(reverse=True)

    trips = []  # each element is the current load of a trip

    for w in weights:
        placed = False
        # Try to fit into an existing trip
        for i in range(len(trips)):
            if trips[i] + w <= limit:
                trips[i] += w
                placed = True
                break
        # If not placed in any existing trip, start a new one
        if not placed:
            trips.append(w)

    return len(trips)

from typing import List

def minimum_trips(weights: List[int], limit: int) -> int:
    # If any package exceeds the limit, it cannot be delivered without exceeding.
    # We return -1 to indicate impossibility.
    if any(w > limit for w in weights):
        return -1

    # Sort weights in descending order
    weights.sort(reverse=True)

    trips = []  # each element is the current load of a trip

    for w in weights:
        # Find the trip with the smallest remaining capacity that can still fit w
        best_trip_index = -1
        best_remaining = float('inf')

        for i in range(len(trips)):
            remaining = limit - trips[i]
            if remaining >= w:
                if remaining < best_remaining:
                    best_remaining = remaining
                    best_trip_index = i

        if best_trip_index != -1:
            trips[best_trip_index] += w
        else:
            trips.append(w)

    return len(trips)

