from typing import List, Optional

class PriorityQueue:
    def __init__(self, items: Optional[List[int]] = None, priorities: Optional[List[int]] = None):
        """
        Initialize the priority queue.

        - If both items and priorities are provided, they must have the same length.
        - If only items are provided, default priority = item value.
        - If only priorities are provided, we assume items = [0, 0, ..., 0] (or you can adapt).
        - If neither, start with an empty queue.
        """
        self._pq: List[tuple] = []  # heap of (priority, index, item)
        self._counter = 0  # to break ties consistently
        self._seen_items: set = set()  # to avoid duplicate items with same priority if needed

        if items is None and priorities is None:
            return

        if items is not None and priorities is not None:
            if len(items) != len(priorities):
                raise ValueError("items and priorities must have the same length")
            for item, priority in zip(items, priorities):
                self.push(item, priority)
        elif items is not None:
            for item in items:
                self.push(item)
        elif priorities is not None:
            # Fallback: create dummy items (e.g., 0) with given priorities
            for priority in priorities:
                self.push(0, priority)

    def size(self) -> int:
        return len(self._pq)

    def push(self, item: int, priority: Optional[int] = None) -> None:
        """
        Insert an item into the priority queue.
        If priority is None, use the item's value as the priority.
        """
        if priority is None:
            priority = item
        # Use (priority, counter, item) to ensure stable ordering
        heapq.heappush(self._pq, (priority, self._counter, item))
        self._counter += 1

    def pop(self) -> int:
        """
        Remove and return the item with the lowest priority.
        If the queue is empty, raise an error (or handle gracefully as required).
        """
        if not self._pq:
            raise IndexError("pop from empty priority queue")
        _, _, item = heapq.heappop(self._pq)
        return item

from typing import List

def min_skill_diff(n: int, skill_levels: List[int]) -> int:
    skill_levels.sort()
    team1 = 0
    team2 = 0
    left, right = 0, n - 1

    while left <= right:
        if left == right:
            # Last element goes to the team with smaller current sum
            if team1 <= team2:
                team1 += skill_levels[left]
            else:
                team2 += skill_levels[left]
            break

        # Assign smallest to one team, largest to the other
        team1 += skill_levels[left]
        team2 += skill_levels[right]
        left += 1
        right -= 1

    return abs(team1 - team2)

def sum_of_squares(dict_of_lists):
    """
    Takes a dictionary where each key is a string and each value is a list of integers.
    Returns a new dictionary where each key maps to the sum of the squares of the integers
    in the corresponding list.

    Example:
        Input:  {"a": [1, 2, 3], "b": [4, 5], "c": [6]}
        Output: {"a": 14, "b": 41, "c": 36}
    """
    result = {}
    for key, numbers in dict_of_lists.items():
        result[key] = sum(x * x for x in numbers)
    return result

