from collections import deque, defaultdict
from typing import List, Tuple

def earliest_time_to_be_virus_free(n: int, m: int, edges: List[Tuple[int, int]], k: int, starting_devices: List[int]) -> int:
    # Build adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Initialize distance array with -1 (unvisited)
    dist = [-1] * (n + 1)
    queue = deque()

    # Add all starting devices
    for start in starting_devices:
        if 1 <= start <= n:
            dist[start] = 0
            queue.append(start)

    # BFS
    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    # Check if all nodes are visited
    for i in range(1, n + 1):
        if dist[i] == -1:
            return -1

    # Return the maximum distance
    return max(dist[1:])

